LoginManageList::LoginManageList() {
	InitializeCriticalSection(&m_cs);
}

LoginManageList::~LoginManageList() {
	DeleteCriticalSection(&m_cs);
}

bool LoginManageList::Insert(const std::string& name) {
	bool ret = false;
	Lock();
	if (!_Query(name)) {
		m_list.push_back(name);
		ret = true;
	}
	UnLock();
	return ret;
}

bool LoginManageList::Remove(const std::string& name) {
	bool ret = false;
	Lock();

	auto it = std::find(m_list.begin(), m_list.end(), name);
	if (it != m_list.end()) {
		ret = true;
		m_list.erase(it);
	}
	UnLock();
	return ret;
}

bool LoginManageList::Query(const std::string& name) {
	bool ret = false;
	Lock();
	ret = _Query(name);
	UnLock();
	return ret;
}

bool LoginManageList::_Query(const std::string& name) {
	auto it = std::find(m_list.cbegin(), m_list.cend(), name);
	if (it != m_list.end()) {
		return true;
	}
	return false;
}

void LoginManageList::Lock() {
	EnterCriticalSection(&m_cs);
}

void LoginManageList::UnLock() {
	LeaveCriticalSection(&m_cs);
}

bool GroupServerApp::OnConnect(DataSocket* datasock) //返回值:true-允许连接,false-不允许连接
{
	datasock->SetRecvBuf(64 * 1024);
	datasock->SetSendBuf(64 * 1024);
	if (!datasock->IsServer()) {
		LogLine l_line(g_LogConnect);
		l_line << newln << "AccountServer:" << datasock->GetPeerIP() << "," << datasock->GetPeerPort() << "come ! Socket num:"
			   << GetSockTotal() + 1 << endln;
		std::cout << "AccountServer:" << datasock->GetPeerIP() << "," << datasock->GetPeerPort() << "come ! Socket num:" << GetSockTotal() + 1 << std::endl;
	} else {
		LogLine l_line(g_LogConnect);
		l_line << newln << "GateServer:" << datasock->GetPeerIP() << "," << datasock->GetPeerPort() << "come ! Socket num:"
			   << GetSockTotal() + 1 << endln;
		std::cout << "GateServer:" << datasock->GetPeerIP() << "," << datasock->GetPeerPort() << "come ! Socket num:" << GetSockTotal() + 1 << std::endl;
	}
	return true;
}

void GroupServerApp::OnDisconnect(DataSocket* datasock, int reason) {
	if (!datasock->IsServer()) {
		m_mtxlogin.lock();
		try {
			if (g_gpsvr->m_acctsock == datasock) {
				g_gpsvr->m_acctsock = nullptr;
			}
		} catch (...) {
		}
		m_mtxlogin.unlock();
		LogLine l_line(g_LogConnect);
		l_line << newln << "AccountServer:" << datasock->GetPeerIP() << "," << datasock->GetPeerPort() << "go ! Socket num:"
			   << GetSockTotal() << "reason=(" << reason << ")" << GetDisconnectErrText(reason)
			   << endln;
		std::cout << "AccountServer:" << datasock->GetPeerIP() << "," << datasock->GetPeerPort() << "go ! Socket num:" << GetSockTotal() << "reason=" << GetDisconnectErrText(reason).c_str() << std::endl;

		if (reason == DS_SHUTDOWN || reason == DS_DISCONN) {
			return;
		}

		std::cout << "after 5 seconds reconnect......" << std::endl;
		Sleep(5000);
		InitACTSvrConnect(*g_gpsvr);
	} else {
		auto l_gate = static_cast<GateServer*>(datasock->GetPointer());
		if (l_gate) {
			m_mtxlogin.lock();
			try {
				l_gate->SetDataSock(nullptr);
			} catch (...) {
			}
			m_mtxlogin.unlock();
			LogLine l_line(g_LogConnect);
			l_line << newln << "GateServer:" << datasock->GetPeerIP() << "," << datasock->GetPeerPort() << "go ! Socket num:"
				   << GetSockTotal() << "reason=(" << reason << ")" << GetDisconnectErrText(reason)
				   << endln;
			std::cout << "GateServer:" << datasock->GetPeerIP() << "," << datasock->GetPeerPort() << "go ! Socket num:" << GetSockTotal() << "reason=" << GetDisconnectErrText(reason).c_str() << std::endl;

			Player* player{nullptr};
			RunChainGetArmor<Player> l(m_plylst);
			while (player = m_plylst.GetNextItem()) {
				if (player->m_gate == l_gate) {
					RPacket l_rpk;
					TP_USER_LOGOUT(player, datasock, l_rpk);
				}
			}
			l.unlock();
		}
	}
}

WPacket GroupServerApp::OnServeCall(DataSocket* datasock, RPacket& pk) {
	const unsigned short l_cmd = pk.ReadCmd();
	switch (l_cmd) {
	case CMD_TP_LOGIN:
		return TP_LOGIN(datasock, pk);
	case CMD_TP_USER_LOGIN:
		return TP_USER_LOGIN(datasock, pk);
	case CMD_TP_REQPLYLST:
		return TP_REQPLYLST(datasock, pk);
	case CMD_TP_SYNC_PLYLST:
		return TP_SYNC_PLYLST(datasock, pk);
	case CMD_OS_LOGIN:
		return OS_LOGIN(datasock, pk);
	}

	auto* player = ToPointer<Player>(pk.ReverseReadAddress());
	const uintptr_t l_gtaddr = pk.ReverseReadAddress();
	uintptr_t playergt = 0;
	try {
		playergt = player->m_gtAddr;
	} catch (...) {
		player = nullptr;
	}
	if (!player || l_gtaddr != playergt) {
		WPacket l_retpk = GetWPacket();
		l_retpk.WriteShort(ERR_PT_KICKUSER);
		return l_retpk;
	}

	switch (l_cmd) {
	case CMD_TP_USER_LOGOUT:
		return TP_USER_LOGOUT(player, datasock, pk);
	case CMD_TP_BGNPLAY:
		return TP_BGNPLAY(player, datasock, pk);
	case CMD_TP_ENDPLAY:
		return TP_ENDPLAY(player, datasock, pk);
	case CMD_TP_NEWCHA:
		return TP_NEWCHA(player, datasock, pk);
	case CMD_TP_DELCHA:
		return TP_DELCHA(player, datasock, pk);
	case CMD_TP_CREATE_PASSWORD2:
		return TP_CREATE_PASSWORD2(player, datasock, pk);
	case CMD_TP_UPDATE_PASSWORD2:
		return TP_UPDATE_PASSWORD2(player, datasock, pk);
	}
	return WPacket(nullptr);
}

