WPacket GroupServerApp::TP_USER_LOGOUT(Player* ply, DataSocket* datasock, RPacket& pk) {
	WPacket l_retpk = GetWPacket();
	if (!ply || !ply->m_gtAddr) {
		l_retpk.WriteShort(ERR_PT_INERR);
		return l_retpk;
	}

	uLong l_acctid = ply->m_acctid;
	if (!l_acctid || l_acctid != ply->m_acctid) {
		l_retpk.WriteShort(ERR_PT_INERR);
		return l_retpk;
	}
	RunChainGetArmor<Player> l(m_plylst);

	ply->EndPlay(datasock);

	if (ply->EndRun()) {
		if (ply->m_currcha != -1) {
			//发送结束计费命令
			WPacket wpk = GetWPacket();
			wpk.WriteCmd(CMD_PA_USER_BILLEND);
			wpk.WriteString(ply->m_acctname.c_str());
			SendData(m_acctsock, wpk);
		}

		//向AccountServer发送LogOut命令
		WPacket wpk = GetWPacket();
		wpk.WriteCmd(CMD_PA_USER_LOGOUT);
		wpk.WriteLong(ply->m_acctLoginID);
		wpk.WriteLong(ply->m_sessid);
		SendData(m_acctsock, wpk);
		//登出成功
		LogLine l_line(g_LogGrpServer);
		l_line << newln << "(" << ply->m_clientip << "):[" << ply->m_acctname << "]logout,\t online/total:" << m_plylst.GetTotal() << "/" << long(m_curChaNum);
	} else {
		LogLine l_line(g_LogGrpServer);
		l_line << newln << "(" << ply->m_clientip << "):[" << ply->m_acctname << "]logout,\t online/total:" << m_plylst.GetTotal() << "/" << long(m_curChaNum);
	}

	if (ply->m_bWG) {
		m_curWGChaNum--;
	}

	// 删除列表
	m_LoginList.Remove(ply->m_acctname);
	ply->Free();
	l.unlock();
	//返回成功错误码
	l_retpk.WriteShort(ERR_SUCCESS);
	return l_retpk;
}

WPacket GroupServerApp::TP_BGNPLAY(Player* ply, DataSocket* datasock, RPacket& pk) {
	WPacket retpk = GetWPacket();
	if (ply->m_currcha >= 0) {
		retpk.WriteShort(ERR_PT_INERR); //应该日值的内部错误
		return retpk;
	}

	unsigned short l_len;
	const char* l_cha = pk.ReadString(&l_len);
	if (!l_cha || l_len > CommConstants::Character::name_max_length) {
		retpk.WriteShort(ERR_PT_INERR); //应该日值的内部错误
		return retpk;
	}

	MutexArmor l_lockCha(ply->m_mtxCha);
	ply->m_bp_currcha = ply->FindIndexByChaName(l_cha);
	if (ply->m_bp_currcha < 0) { //本帐号没有这个角色
		retpk.WriteShort(ERR_PT_INVALIDCHA);
		return retpk;
	}
	if (ply->m_password.length() <= 0) {
		retpk.WriteShort(ERR_PT_INVALID_PW2);
		return retpk;
	}
	//合法角色
	MutexArmor l_lockDB(m_mtxDB);
	if (m_tblcharaters->FetchRowByChaID(ply->m_chaid[ply->m_bp_currcha]) < 1) {
		retpk.WriteShort(ERR_PT_INERR);
		return retpk;
	}

	const int l_maxval = atoi(m_cfg["Database"]["MaxVal"]);
	if (l_maxval && (m_tblcharaters->GetStr() > l_maxval ||
					 m_tblcharaters->GetDex() > l_maxval ||
					 m_tblcharaters->GetAgi() > l_maxval ||
					 m_tblcharaters->GetCon() > l_maxval ||
					 m_tblcharaters->GetSta() > l_maxval ||
					 m_tblcharaters->GetLuk() > l_maxval)) {
		retpk.WriteShort(ERR_PT_BADBOY);
		WPacket wpk = GetWPacket();
		wpk.WriteCmd(CMD_MC_SYSINFO);
		char l_buf[256];
		CFormatParameter param(2);
		param.setString(0, ply->m_acctname.c_str());
		param.setString(1, ply->m_chaname[ply->m_bp_currcha].c_str());
		RES_FORMAT_STRING(GP_GROUPSERVERAPPSERV_CPP_00002, param, l_buf);
		wpk.WriteString(l_buf);

		Player* playerlst[10240];
		short playernum = 0;

		RunChainGetArmor<Player> l(m_plylst);
		for (Player* playerr = m_plylst.GetNextItem(); playerr; playerr = m_plylst.GetNextItem()) {
			if (playerr->m_bp_currcha < 0) {
				continue;
			}
			playerlst[playernum] = playerr;
			playernum++;
		}
		l.unlock();
		SendToClient(playerlst, playernum, wpk);
		ply->m_currcha = -1;
		return retpk;
	}

	//返回成功相关信息
	retpk.WriteShort(ERR_SUCCESS); //选角色成功返回
	retpk.WriteString(ply->m_password.c_str());
	retpk.WriteLong(ply->m_chaid[ply->m_bp_currcha]); //角色ID
	retpk.WriteLong(ply->m_chaid[ply->m_bp_currcha]); //WorldID
	retpk.WriteString(m_tblcharaters->GetMap());	  //上次下线的地图名
	short swiner = 0;
	for (int i = 0; i < MAXORDERNUM; i++) {
		if (ply->m_chaid[ply->m_bp_currcha] == m_tbLparam->GetOrderData(i)->nid) {
			swiner = i + 1;
			break;
		}
	}
	retpk.WriteShort(swiner);
	LogLine l_line(g_LogGrpServer);
	l_line << newln << "(" << ply->m_clientip << "):[" << ply->m_acctname << "]select char[" << l_cha
		   << "]begin play...，\t online/total:" << m_plylst.GetTotal() << "/"
		   << long(m_curChaNum);

	return retpk;
}

WPacket GroupServerApp::TP_ENDPLAY(Player* ply, DataSocket* datasock, RPacket& pk) {
	WPacket l_retpk = GetWPacket();
	if (ply->m_currcha < 0) {
		l_retpk.WriteShort(ERR_PT_INERR); //应该日值的系统不一致错误
	} else {
		l_retpk.WriteShort(ERR_SUCCESS); //重选角色成功返回
		ply->EndPlay(datasock);

		LogLine l_line(g_LogGrpServer);
		l_line << newln << "(" << ply->m_clientip << "):[" << ply->m_acctname << "]exit char["
			   << ply->m_chaname[ply->m_currcha] << "]begin entry select char UI...，\t online/total:"
			   << m_plylst.GetTotal() << "/" << long(m_curChaNum);
		l_line << endln;

		ply->m_currcha = -1; //置为无效的当前角色
		ply->EndPlayReset();
		//发送结束计费命令
		WPacket wpk = GetWPacket();
		wpk.WriteCmd(CMD_PA_USER_BILLEND);
		wpk.WriteString(ply->m_acctname.c_str());
		SendData(m_acctsock, wpk);

		//从数据库里面取出角色表
		GetCHAsFromDBByPlayer(ply, l_retpk);
	}
	return l_retpk;
}

void GroupServerApp::MP_ENTERMAP(Player* ply, DataSocket* datasock, RPacket& pk) {
	const auto l_isSwitch = static_cast<bool>(pk.ReadChar());
	if (!l_isSwitch && ply->m_currcha < 0) {
		MP_ONLINE(ply);
	} else if (l_isSwitch && ply->m_currcha >= 0) {
		MP_SWITCH(ply);
	}
}

void GroupServerApp::MP_ONLINE(Player* ply) {
	MutexArmor l_lockDB(m_mtxDB);
	ply->m_currcha = ply->m_bp_currcha;
	ply->m_bp_currcha = -1;
	m_tblcharaters->SetAddr(ply->m_chaid[ply->m_currcha], ToAddress(ply));
	++m_curChaNum;
	LogLine l_line(g_LogGrpServer);
	l_line << newln << "(" << ply->m_clientip << "):[" << ply->m_acctname << "] char ["
		   << ply->m_chaname[ply->m_currcha] << "]entry map server begin play...，\t online/total:"
		   << m_plylst.GetTotal() << "/" << long(m_curChaNum);
	l_line << endln;

	//发送开始计费命令
	WPacket wpk = GetWPacket();
	wpk.WriteCmd(CMD_PA_USER_BILLBGN);
	wpk.WriteString(ply->m_acctname.c_str());
	wpk.WriteString(ply->m_passport.c_str());
	SendData(m_acctsock, wpk);

	ply->CheckEstop();

	PC_FRND_INIT(ply);
	PC_GULD_INIT(ply);
	PC_MASTER_INIT(ply);
}

